// W430 logic proof: one headless assertion per numbered rule, against the real engine (src/data, djinns, engine).
// Rules come from the published rulebook + summary sheet, NOT from the earlier tests.
// Run: node logic-test.js            -> prints one line per failing rule, then totals
//      node logic-test.js --md       -> rewrites RULES-CHECKLIST.md from the rule table below
// Source tags: RB = rulebook text, SS = player summary sheet, UV = printed on pieces, not in any text I could read (engine consistency only).
const fs = require('fs'), vm = require('vm'), path = require('path');
const C = { console, Math, Date, JSON, setTimeout, clearTimeout, performance: { now: Date.now }, window: {}, document: {} }; vm.createContext(C);
for (const f of ['data', 'djinns', 'engine']) vm.runInContext(fs.readFileSync(path.join(__dirname, 'src', f + '.js'), 'utf8'), C, { filename: f });
const run = s => vm.runInContext(s, C); run('UI.sim=false;');
const g = () => run('G'), DJ = run('DJ'), TILEDEF = run('TILEDEF'), SETVP = run('SETVP');
const RULES = [];
const R = (grp, src, text, fn) => RULES.push({ grp, src, text, fn });
const J = JSON.stringify;
const J2 = v => JSON.stringify(v, (k, x) => x && typeof x === 'object' && !Array.isArray(x) ? Object.keys(x).sort().reduce((o, q) => (o[q] = x[q], o), {}) : x);
const eq = (exp, got, what) => { if (J2(exp) !== J2(got)) { const e = new Error('x'); e.exp = what ? what + ' ' + J(exp) : J(exp); e.got = J(got); throw e } };
// ---------- scene helpers ----------
let seedN = 500;
function fresh(np = 3, ex = {}) {
  run(`DEFSEED=${seedN++};`); C.newGame({ np, ex, seats: Array(np).fill('human') }); const G = g();
  for (const t of G.board) { G.bag.push(...t.m); t.m = []; t.camel = null; t.tent = null; t.palm = 0; t.pal = 0; setK(t.i, 'small') }
  G.market = ['ivory', 'jewels', 'gold', 'papyrus', 'silk', 'spice', 'fish', 'wheat', 'pottery']; return G;
}
function setK(i, k, v) { const t = g().board[i]; t.k = k; t.blue = TILEDEF[k].blue; t.v = v == null ? 6 : v; t.block = TILEDEF[k].block ? 1 : 0 }
function put(i, list) { const G = g(); for (const c of list) { const j = G.bag.indexOf(c); if (j >= 0) G.bag.splice(j, 1); G.board[i].m.push(c) } }
function begin(p = 0) { const G = g(); G.phase = 'turn'; G.bidQueue = []; G.order = G.pl.map(q => ({ p: q.i, k: 0 })); G.turnIdx = p; G.nextBid = []; G.turn = 0; C.startTurn(); return G }
function mv(m) { const r = C.performMove(m); if (!r.success) throw new Error(r.error); return r }
function go(start, drops) { mv({ act: 'start', tile: start }); for (const [tile, c] of drops) mv({ act: 'step', tile, c }) }
const moves = () => C.validMoves();
const has = f => moves().some(f);
function atStep(step, tile, color, n, tribeDone) { fresh(3); const G = begin(0); G.step = step; G.act = { tile, color, n: n || 1, tribeDone: !!tribeDone, tileDone: false }; return G }
const P = i => g().pl[i];
const blues = i => { const G = g(); return C.AROUND(i).filter(j => G.board[j].blue && !G.board[j].block).length };
// ============================================================ SETUP
R('Setup', 'RB', '30 tiles are laid in a 5 x 6 rectangle (6 columns, 5 rows).', () => { const G = fresh(); eq([6, 5, 30], [G.W, G.H, G.board.length]) });
R('Setup', 'RB', 'Of the 30 tiles, 12 are blue-valued (Hamlets, Shrines) and 18 are red-valued (Bazaars, Oases).', () => { run(`DEFSEED=77`); C.newGame({ np: 3, seats: ['human', 'human', 'human'] }); const G = g(); eq([12, 18], [G.board.filter(t => t.blue).length, G.board.filter(t => !t.blue).length]) });
R('Setup', 'UV', 'Tile mix is 5 Hamlets, 7 Shrines, 6 Oases, 8 Bazaar Stalls, 4 Grand Bazaars (counts printed on the tiles; not in the rulebook text).', () => { run(`DEFSEED=78`); C.newGame({ np: 3, seats: ['human', 'human', 'human'] }); const G = g(), n = {}; G.board.forEach(t => n[t.k] = (n[t.k] || 0) + 1); eq({ village: 5, sacred: 7, oasis: 6, small: 8, large: 4 }, n) });
R('Setup', 'RB', '90 meeples: 16 yellow Advisors, 20 white Sages, 18 blue Masons, 18 green Traders, 18 red Shadows; shaken out 3 per tile, so the bag is empty after setup.', () => { run(`DEFSEED=79`); C.newGame({ np: 3, seats: ['human', 'human', 'human'] }); const G = g(), n = {}; G.board.forEach(t => { if (t.m.length !== 3) n.bad = 1; t.m.forEach(c => n[c] = (n[c] || 0) + 1) }); eq({ vizier: 16, elder: 20, builder: 18, merchant: 18, assassin: 18 }, Object.assign(n, { bag: undefined }) && { vizier: n.vizier, elder: n.elder, builder: n.builder, merchant: n.merchant, assassin: n.assassin }); eq(0, G.bag.length, 'bag') });
R('Setup', 'RB', '54 resource cards: 36 goods (Ivory, Jewels, Gold x2; Papyrus, Silk, Spice x4; Fish, Wheat, Pottery x6) and 18 Mystics. 9 are laid face up.', () => { run(`DEFSEED=80`); C.newGame({ np: 3, seats: ['human', 'human', 'human'] }); const G = g(), n = {}; G.market.concat(G.rdeck).forEach(c => n[c] = (n[c] || 0) + 1); eq({ ivory: 2, jewels: 2, gold: 2, papyrus: 4, silk: 4, spice: 4, fish: 6, wheat: 6, pottery: 6, fakir: 18 }, n); eq(9, G.market.length, 'face up') });
R('Setup', 'RB', '22 Djinn cards; the top 3 are laid face up.', () => { run(`DEFSEED=81`); C.newGame({ np: 3, seats: ['human', 'human', 'human'] }); const G = g(); eq([3, 22], [G.djRow.length, G.djRow.length + G.djDeck.length]) });
R('Setup', 'RB', 'Each player starts with 50 gold coins.', () => { const G = fresh(4); eq([50, 50, 50, 50], G.pl.map(p => p.coins)) });
R('Setup', 'RB', '3-4 players: 8 camels and 1 turn marker each. 2 players: 11 camels and 2 turn markers each.', () => { const a = fresh(2), r2 = [P(0).camels, P(0).markers, a.bidQueue.length]; const b = fresh(3), r3 = [P(0).camels, P(0).markers, b.bidQueue.length]; const c = fresh(4), r4 = [P(0).camels, P(0).markers, c.bidQueue.length]; eq([[11, 2, 4], [8, 1, 3], [8, 1, 4]], [r2, r3, r4]) });
R('Setup', 'RB', 'The bank holds 12 palm trees and 10 palaces.', () => { const G = fresh(); eq({ palm: 12, pal: 10 }, G.sup) });
R('Setup', 'RB', 'The initial bid order is random (turn markers are placed randomly on the bid order track).', () => { const first = new Set(); for (let s = 1; s <= 30; s++) { run(`DEFSEED=${s}`); C.newGame({ np: 4, seats: Array(4).fill('human') }); first.add(g().bidQueue[0].p) } eq(true, first.size > 1) });
// ============================================================ BIDDING
R('Bidding', 'UV', 'The turn order track has 9 spots costing 18, 12, 8, 5, 3, 1, 0, 0, 0 gold (3 spots at 0). The rulebook examples show the 5, 3, 1 and 0 spots; 18, 12 and 8 are from the printed track.', () => { const G = fresh(); eq([18, 12, 8, 5, 3, 1, 0, 0, 0], G.track.map(t => t.cost)) });
function bidCost(cost) { const G = g(); const m = moves().find(m => m.act === 'bid' && G.track[m.spot].cost === cost && !m.fk); if (!m) throw new Error('no bid of cost ' + cost); const who = G.bidQueue[0].p; mv(m); return who }
R('Bidding', 'RB', 'The bidder immediately pays the cost of the chosen spot to the bank.', () => { const G = fresh(3), who = G.bidQueue[0].p; bidCost(8); eq(42, P(who).coins) });
R('Bidding', 'RB', 'Except at 0, no two markers may sit on the same spot: a taken paid spot cannot be chosen again.', () => { fresh(3); bidCost(8); eq(false, has(m => m.act === 'bid' && g().track[m.spot].cost === 8)) });
R('Bidding', 'RB', 'At most 3 markers on the 0 spots: with three at 0 the next bidder must bid at least 1.', () => { fresh(4); bidCost(0); bidCost(0); bidCost(0); const costs = moves().filter(m => m.act === 'bid').map(m => g().track[m.spot].cost); eq(true, costs.length > 0 && costs.every(c => c >= 1), 'costs ' + J(costs)) });
R('Bidding', 'RB', 'Players act in order of the spots they bid: highest-cost spot first.', () => { const G = fresh(3); const a = bidCost(3), b = bidCost(8), c = bidCost(1); eq([b, a, c], G.order.map(m => m.p)) });
R('Bidding', 'RB', 'Among markers on 0 the LAST bidder plays first of them (earlier 0 bids are pushed down the aisle and play last).', () => { const G = fresh(3); const a = bidCost(0), b = bidCost(0), c = bidCost(0); eq([c, b, a], G.order.map(m => m.p)) });
R('Bidding', 'RB', 'At the start of your turn your marker moves to the first empty bid-order spot: next round bids in the order of play.', () => { const G = fresh(3); put(14, ['vizier']); put(15, ['vizier']); bidCost(3); bidCost(8); bidCost(1); const play = G.order.map(m => m.p); for (let i = 0; i < 3; i++) C.endTurn(); eq(play, G.bidQueue.map(m => m.p)); eq('bid', G.phase) });
R('Bidding', 'RB', '2 players: each owns two markers, so each plays twice per round, even twice in a row when the markers sit on adjacent spots.', () => { const G = fresh(2); const cnt = { 0: 0, 1: 0 }; const costFor = [[18, 12], [3, 1]]; for (let i = 0; i < 4; i++) { const who = G.bidQueue[0].p; const c = costFor[who][cnt[who]++]; bidCost(c) } eq([0, 0, 1, 1], G.order.map(m => m.p)) });
R('Bidding', 'RB', 'Gold paid for turn order goes to the bank and the bidder keeps no refund (coins fall by exactly the price, for every price).', () => { for (const [cost, left] of [[18, 32], [12, 38], [5, 45], [3, 47], [1, 49], [0, 50]]) { const G = fresh(3), who = G.bidQueue[0].p; bidCost(cost); eq(left, P(who).coins, 'cost ' + cost) } });
// ============================================================ MOVEMENT
R('Movement', 'RB', 'You choose a tile holding at least 1 meeple and take ALL its meeples in hand; a tile without meeples cannot be chosen.', () => { fresh(); put(14, ['vizier', 'elder', 'vizier']); put(15, ['elder']); begin(0); eq(false, has(m => m.act === 'start' && m.tile === 20), 'empty tile'); mv({ act: 'start', tile: 14 }); eq([3, 0], [g().move.hand.length, g().board[14].m.length]) });
R('Movement', 'RB', 'You drop exactly 1 meeple on each tile you pass through, starting with a tile adjacent to the one you lifted from.', () => { const G = fresh(); put(14, ['vizier', 'elder']); put(15, ['elder']); put(9, ['vizier']); begin(0); go(14, [[15, 'elder'], [9, 'vizier']]); eq([2, 1], [G.board[15].m.length, 0 + 1]); eq(0, G.board[14].m.length) });
R('Movement', 'RB', 'No diagonal moves: every drop is on a tile sideways-adjacent to the previous tile.', () => { fresh(); put(14, ['vizier', 'elder']); put(21, ['vizier', 'elder']); put(15, ['elder']); put(9, ['vizier']); begin(0); mv({ act: 'start', tile: 14 }); const bad = moves().filter(m => m.act === 'step' && ![8, 20, 13, 15].includes(m.tile)); eq(0, bad.length, 'non-adjacent step tiles ' + J(bad.map(m => m.tile))) });
R('Movement', 'RB', 'No immediate backtracking: you cannot step back onto the tile you just left, even if it holds your colour.', () => { fresh(); put(14, ['vizier', 'elder', 'elder']); put(15, ['vizier']); put(17, ['vizier']); begin(0); mv({ act: 'start', tile: 14 }); mv({ act: 'step', tile: 15, c: 'elder' }); mv({ act: 'step', tile: 16, c: 'elder' }); const t = moves().filter(m => m.act === 'step').map(m => m.tile); eq([17], t, 'steps from 16 (15 would be a backtrack)') });
R('Movement', 'RB', 'You may re-enter a tile later in the same move (a loop needs 5 meeples); only the immediate step back is banned. A meeple dropped earlier in the move counts as "already there" for the last-colour rule.', () => { const G = fresh(); put(14, ['vizier', 'elder', 'merchant', 'builder', 'vizier']); begin(0); go(14, [[15, 'vizier'], [21, 'elder'], [20, 'merchant'], [14, 'builder'], [15, 'vizier']]); eq('tribe', G.step); eq(2, G.act.n); eq('vizier', G.act.color) });
R('Movement', 'RB', 'Last meeple same colour: the last meeple dropped must land on a tile that already holds a meeple of its colour; a start tile with no such ending is not selectable.', () => { fresh(); put(14, ['vizier', 'elder']); put(15, ['elder']); begin(0); eq(false, has(m => m.act === 'start' && m.tile === 14)); });
R('Movement', 'RB', 'You choose the order in which you drop the colours from your hand (both orders are offered when both are legal).', () => { fresh(); put(14, ['vizier', 'elder']); put(15, ['elder']); put(9, ['vizier']); put(13, ['vizier']); put(12, ['elder']); begin(0); mv({ act: 'start', tile: 14 }); const cs = new Set(moves().filter(m => m.act === 'step').map(m => m.c)); eq(['elder', 'vizier'], [...cs].sort()) });
R('Movement', 'RB', 'You may pass through empty tiles (dropping one meeple on each) but may never end on an empty tile.', () => { const G = fresh(); put(14, ['vizier', 'elder']); put(9, ['vizier']); begin(0); mv({ act: 'start', tile: 14 }); eq(false, has(m => m.act === 'step' && m.tile === 15 && m.c === 'vizier'), 'v onto empty tile 15 as non-last'); mv({ act: 'step', tile: 15, c: 'elder' }); eq(true, has(m => m.act === 'step' && m.tile === 9 && m.c === 'vizier')); eq(false, has(m => m.act === 'step' && m.tile === 16)) });
R('Movement', 'RB', 'Colour rule uses the whole hand: a drop is only allowed if the rest of the hand can still reach a legal ending.', () => { fresh(); put(14, ['vizier', 'elder', 'merchant']); put(8, ['merchant']); begin(0); mv({ act: 'start', tile: 14 }); const cs = moves().filter(m => m.act === 'step' && m.tile === 13).map(m => m.c).sort(); eq(['elder', 'vizier'], cs, 'colours droppable on 13 (merchant first would strand v+e)') });

function legalOracle(M, W, H) { // independent brute force of the movement rules on an array of meeple arrays
  const adj = i => { const r = Math.floor(i / W), c = i % W, o = []; if (r > 0) o.push(i - W); if (r < H - 1) o.push(i + W); if (c > 0) o.push(i - 1); if (c < W - 1) o.push(i + 1); return o };
  const done = (at, prev, hand, B) => { for (const nx of adj(at)) { if (nx === prev) continue; for (const c of new Set(hand)) { if (hand.length === 1) { if (B[nx].includes(c)) return true; continue } const h = hand.slice(); h.splice(h.indexOf(c), 1); B[nx].push(c); const ok = done(nx, at, h, B); B[nx].pop(); if (ok) return true } } return false };
  const opts = (at, prev, hand, B) => { const o = []; for (const nx of adj(at)) { if (nx === prev) continue; for (const c of new Set(hand)) { const h = hand.slice(); h.splice(h.indexOf(c), 1); if (!h.length) { if (B[nx].includes(c)) o.push([nx, c]); continue } B[nx].push(c); if (done(nx, at, h, B)) o.push([nx, c]); B[nx].pop() } } return o };
  return { adj, opts, starts: B => B.map((m, i) => m.length && opts(i, -1, m.slice(), B.map((x, j) => j === i ? [] : x.slice())).length ? i : -1).filter(i => i >= 0) } }
R('Movement', 'RB', 'Exactness check against an independent brute-force of the movement rules on 400 random boards: the engine offers exactly the legal start tiles and exactly the legal (tile, colour) drops at every step of random full moves.', () => {
  const cols = ['vizier', 'elder', 'merchant', 'builder', 'assassin']; let seed = 12345; const rnd = n => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n };
  for (let b = 0; b < 400; b++) { const G = fresh(3); const dens = 1 + rnd(3); const M = []; for (let i = 0; i < 30; i++) { M.push([]); const k = rnd(dens + 1); for (let j = 0; j < k; j++) M[i].push(cols[rnd(b % 2 === 0 ? 2 : 5)]) } for (let i = 0; i < 30; i++) put(i, M[i]);
    begin(0); const O = legalOracle(M, 6, 5); const want = O.starts(M).sort((a, c) => a - c), got = C.legalStarts().sort((a, c) => a - c); eq(want, got, 'board ' + b + ' start tiles');
    if (!want.length) continue; const s0 = want[rnd(want.length)]; mv({ act: 'start', tile: s0 }); const B = M.map(m => m.slice()); let hand = B[s0].slice(); B[s0] = []; let at = s0, prev = -1;
    while (hand.length) { const wantS = O.opts(at, prev, hand, B).map(x => x.join(':')).sort(), gotS = moves().filter(m => m.act === 'step').map(m => m.tile + ':' + m.c).sort(); eq(wantS, gotS, 'board ' + b + ' step options at ' + at + ' hand ' + hand.join(',')); const [nx, c] = O.opts(at, prev, hand, B)[rnd(wantS.length)]; mv({ act: 'step', tile: nx, c }); B[nx].push(c); hand.splice(hand.indexOf(c), 1); prev = at; at = nx } } });
R('Movement', 'RB', 'You must make a meeple move if one is legal (no passing, no ending the turn before moving); a tribe action cannot be skipped while a kill target exists.', () => { fresh(); put(14, ['vizier']); put(15, ['vizier']); put(20, ['assassin']); put(21, ['assassin']); put(22, ['builder']); begin(0); eq(false, has(m => m.act === 'end' || m.act === 'sell' || m.act === 'tile')); go(20, [[21, 'assassin']]); eq(false, has(m => m.none), 'kill target exists'); eq(false, has(m => m.act === 'end')) });
// ============================================================ TILE CONTROL
function scene(c, pre, F = 15) { const G = fresh(); put(14, [c]); put(F, pre); begin(0); go(14, [[F, c]]); return G }
R('Tile control', 'RB', 'After the move you take back the last meeple dropped plus ALL meeples of that colour already on the tile.', () => { const G = scene('elder', ['elder', 'elder']); eq([3, 'elder', 'tribe'], [G.act.n, G.act.color, G.step]); eq(0, G.board[15].m.length) });
R('Tile control', 'RB', 'If that empties the tile (only that colour was there), you take control by placing a camel on it.', () => { const G = scene('elder', ['elder', 'elder']); eq([0, 7], [G.board[15].camel, P(0).camels]) });
R('Tile control', 'RB', 'If other colours remain on the tile you do not take control.', () => { const G = scene('elder', ['elder', 'vizier']); eq([null, 8], [G.board[15].camel, P(0).camels]) });
R('Tile control', 'RB', 'Once a camel is on a tile it never changes owner: emptying a controlled tile gives no new camel.', () => { const G = fresh(); G.board[15].camel = 1; P(1).camels = 7; put(14, ['elder']); put(15, ['elder']); begin(0); go(14, [[15, 'elder']]); eq([1, 8, 7], [G.board[15].camel, P(0).camels, P(1).camels]) });
R('Tile control', 'RB', 'If you have no camels left you cannot take control (tile stays unowned) and the turn continues normally.', () => { const G = fresh(); P(0).camels = 0; put(14, ['elder']); put(15, ['elder']); begin(0); go(14, [[15, 'elder']]); eq([null, 'tribe'], [G.board[15].camel, G.step]) });
R('Tile control', 'RB', 'The tribe action is performed whether or not you took control of the tile.', () => { const G = scene('vizier', ['vizier', 'elder']); mv({ act: 'tribe' }); eq(2, P(0).vz) });
// ============================================================ TRIBES
R('Tribes', 'RB', 'Advisors (yellow): the collected meeples are kept in front of you.', () => { const G = scene('vizier', ['vizier', 'vizier']); mv({ act: 'tribe' }); eq([3, 'tile'], [P(0).vz, G.step]) });
R('Tribes', 'RB', 'Sages (white): the collected meeples are kept in front of you.', () => { const G = scene('elder', ['elder']); mv({ act: 'tribe' }); eq(2, P(0).el) });
R('Tribes', 'RB', 'Traders (green): meeples go back in the bag and you take that many resource cards from the START of the row; the row is not refilled until clean-up.', () => { const G = scene('merchant', ['merchant', 'merchant']); const bag = G.bag.length; mv({ act: 'tribe' }); eq(['ivory', 'jewels', 'gold'], P(0).res); eq([6, bag + 3], [G.market.length, G.bag.length]); eq('papyrus', G.market[0]) });
R('Tribes', 'RB', 'A Mystic taken with Traders is held as a Mystic (not goods).', () => { const G = scene('merchant', ['merchant']); G.market = ['fakir', 'gold', 'fish', 'wheat']; mv({ act: 'tribe' }); eq([1, ['gold']], [P(0).fk, P(0).res]) });
R('Tribes', 'RB', 'Traders with fewer cards in the row than meeples: you take what is there.', () => { const G = scene('merchant', ['merchant', 'merchant']); G.market = ['gold']; mv({ act: 'tribe' }); eq([['gold'], 0], [P(0).res, G.market.length]) });
R('Tribes', 'RB', 'Masons (blue): coins = (number of blue-valued tiles in the 3x3 around the final tile, incl. it) x (builders returned to the bag).', () => { const G = fresh(); for (const i of [8, 9, 14, 21]) setK(i, 'village', 5); put(14, ['builder']); put(15, ['builder', 'builder']); begin(0); P(0).coins = 10; go(14, [[15, 'builder']]); const b = blues(15); mv({ act: 'tribe' }); eq([4, 10 + 4 * 3], [b, P(0).coins]) });
R('Tribes', 'RB', 'The final tile itself counts if it is blue-valued.', () => { const G = fresh(); for (const i of [15, 9]) setK(i, 'village', 5); put(14, ['builder']); put(15, ['builder']); begin(0); P(0).coins = 0; go(14, [[15, 'builder']]); mv({ act: 'tribe' }); eq(2 * 2, P(0).coins) });
R('Tribes', 'RB', 'Masons bonus: discard any number of Mystics; each adds +1 to the multiplier. Mystics are discarded.', () => { const G = fresh(); for (const i of [8, 9, 10, 16]) setK(i, 'sacred', 6); put(14, ['builder']); put(15, ['builder', 'builder']); begin(0); P(0).coins = 0; P(0).fk = 2; go(14, [[15, 'builder']]); mv({ act: 'tribe', fk: 2 }); eq([4 * (3 + 2), 0, 2], [P(0).coins, P(0).fk, G.rdisc.filter(c => c === 'fakir').length]) });
R('Tribes', 'RB', 'Masons: the Mystic bonus is optional and partial use is allowed (1 of 2 Mystics).', () => { const G = fresh(); for (const i of [8, 9]) setK(i, 'village', 5); put(14, ['builder']); put(15, ['builder']); begin(0); P(0).coins = 0; P(0).fk = 2; go(14, [[15, 'builder']]); eq(true, has(m => m.act === 'tribe' && m.fk === 1)); mv({ act: 'tribe', fk: 1 }); eq([2 * (2 + 1), 1], [P(0).coins, P(0).fk]) });
R('Tribes', 'RB', 'Masons return to the bag (not kept).', () => { const G = fresh(); put(14, ['builder']); put(15, ['builder', 'builder']); begin(0); go(14, [[15, 'builder']]); const bag = G.bag.length; mv({ act: 'tribe' }); eq(bag + 3, G.bag.length) });
const kills = () => moves().filter(m => m.act === 'tribe' && m.kill);
R('Tribes', 'RB', 'Shadows (red): kill ONE meeple of any colour on a tile no farther than 1 step per assassin you returned (incl. the one just dropped), counted sideways only. With 2 assassins: distance 2 yes (diagonal = 2), distance 3 no.', () => { const G = fresh(); put(14, ['assassin']); put(15, ['assassin']); for (const i of [16, 17, 22, 19, 12]) put(i, ['builder']); begin(0); go(14, [[15, 'assassin']]); const t = new Set(kills().filter(k => k.kill.tile != null).map(k => k.kill.tile)); eq([16, 17, 22], [...t].sort((a, b) => a - b)) });
R('Tribes', 'RB', 'With 3 assassins the range is 3: a tile 3 away is a legal target, a tile 4 away is not.', () => { const G = fresh(); put(14, ['assassin']); put(15, ['assassin', 'assassin']); put(19, ['builder']); put(18, ['builder']); begin(0); go(14, [[15, 'assassin']]); const t = new Set(kills().filter(k => k.kill.tile != null).map(k => k.kill.tile)); eq([true, false], [t.has(19), t.has(18)]) });
R('Tribes', 'RB', 'Shadow Mystic bonus: each Mystic discarded adds 1 to the range.', () => { const G = fresh(); put(14, ['assassin']); put(15, ['assassin']); put(18, ['builder']); begin(0); P(0).fk = 2; go(14, [[15, 'assassin']]); const k = kills().find(k => k.kill.tile === 18); eq(2, k && k.kill.fk, 'fakirs needed for distance 3') });
R('Tribes', 'RB', 'The assassins and the killed meeple go back to the bag; exactly one meeple dies however many assassins you have.', () => { const G = fresh(); put(14, ['assassin']); put(15, ['assassin', 'assassin']); put(16, ['builder', 'builder']); begin(0); go(14, [[15, 'assassin']]); const bag = G.bag.length; mv({ act: 'tribe', kill: { tile: 16, c: 'builder', fk: 0 } }); eq([1, bag + 3 + 1], [G.board[16].m.length, G.bag.length]) });
R('Tribes', 'RB', 'The victim may stand on the final tile itself (distance 0).', () => { const G = fresh(); put(14, ['assassin']); put(15, ['assassin', 'builder']); begin(0); go(14, [[15, 'assassin']]); eq(true, kills().some(k => k.kill.tile === 15 && k.kill.c === 'builder')) });
R('Tribes', 'RB', 'Alternatively kill ONE yellow Advisors or white Sage that an opponent keeps in front of them.', () => { const G = fresh(); put(14, ['assassin']); put(15, ['assassin']); begin(0); P(1).vz = 2; P(1).el = 1; go(14, [[15, 'assassin']]); eq(true, kills().some(k => k.kill.pl === 1 && k.kill.c === 'vizier') && kills().some(k => k.kill.pl === 1 && k.kill.c === 'elder')); const bag = G.bag.length; mv({ act: 'tribe', kill: { pl: 1, c: 'vizier', fk: 0 } }); eq([1, bag + 2 + 1], [P(1).vz, G.bag.length]) });
R('Tribes', 'RB', 'You cannot kill your own kept meeples, and an opponent\'s other kept things (coins, camels) are not targets.', () => { const G = fresh(); put(14, ['assassin']); put(15, ['assassin']); begin(0); P(0).vz = 3; go(14, [[15, 'assassin']]); eq(false, kills().some(k => k.kill.pl === 0)) });
R('Tribes', 'RB', 'If your kill empties a new tile of all meeples, you take control of it with a camel (a second tile in one turn).', () => { const G = fresh(); put(14, ['assassin']); put(15, ['assassin', 'assassin']); put(16, ['builder']); begin(0); go(14, [[15, 'assassin']]); mv({ act: 'tribe', kill: { tile: 16, c: 'builder', fk: 0 } }); eq([0, 0, 6], [G.board[15].camel, G.board[16].camel, P(0).camels]) });
R('Tribes', 'RB', 'A kill that empties the FINAL tile itself (a different colour was left on it) also gives control of it.', () => { const G = fresh(); put(14, ['assassin']); put(15, ['assassin', 'builder']); begin(0); go(14, [[15, 'assassin']]); eq(null, G.board[15].camel); mv({ act: 'tribe', kill: { tile: 15, c: 'builder', fk: 0 } }); eq([0, 7], [G.board[15].camel, P(0).camels]) });
R('Tribes', 'RB', 'Out of camels: the tile you ended on is claimed first, so the tile emptied by the kill stays unowned.', () => { const G = fresh(); P(0).camels = 1; put(14, ['assassin']); put(15, ['assassin']); put(16, ['builder']); begin(0); go(14, [[15, 'assassin']]); mv({ act: 'tribe', kill: { tile: 16, c: 'builder', fk: 0 } }); eq([0, null, 0], [G.board[15].camel, G.board[16].camel, P(0).camels]) });
R('Tribes', 'RB', 'No Shadow kill target in range: the tribe action is simply done with no kill (turn is not blocked).', () => { const G = fresh(); put(14, ['assassin']); put(15, ['assassin']); begin(0); go(14, [[15, 'assassin']]); eq(true, has(m => m.act === 'tribe' && m.none)); mv({ act: 'tribe', none: 1 }); eq('tile', G.step) });
// ============================================================ TILE ACTIONS
R('Tile actions', 'RB', 'Oasis (compulsory): place 1 palm tree on the tile you ended on.', () => { const G = fresh(); setK(15, 'oasis', 8); put(14, ['vizier']); put(15, ['vizier', 'elder']); begin(0); go(14, [[15, 'vizier']]); mv({ act: 'tribe' }); const m = moves().filter(m => m.act === 'tile'); eq([[{ act: 'tile', place: 15 }]], [m]); mv(m[0]); eq([1, 11], [G.board[15].palm, G.sup.palm]) });
R('Tile actions', 'RB', 'Hamlet (compulsory): place 1 palace on the tile you ended on (no skip offered).', () => { const G = fresh(); setK(15, 'village', 5); put(14, ['vizier']); put(15, ['vizier', 'elder']); begin(0); go(14, [[15, 'vizier']]); mv({ act: 'tribe' }); eq(false, has(m => m.act === 'tile' && m.skip)); mv({ act: 'tile', place: 15 }); eq([1, 9], [G.board[15].pal, G.sup.pal]) });
R('Tile actions', 'RB', 'If the supply of palms/palaces has run out, the compulsory action is ignored.', () => { const G = atStep('tile', 15, 'vizier'); setK(15, 'oasis', 8); G.sup.palm = 0; eq([{ act: 'tile', skip: true }], moves().filter(m => m.act === 'tile')) });
R('Tile actions', 'RB', 'Palms/palaces are placed on the tile even when you did not take control; any number may stack on a tile.', () => { const G = atStep('tile', 15, 'vizier'); setK(15, 'village', 5); G.board[15].pal = 1; G.board[15].camel = 2; mv({ act: 'tile', place: 15 }); eq(2, G.board[15].pal) });
R('Tile actions', 'RB', 'Bazaar Stall (optional): pay 3 gold, take 1 of the first 3 resource cards; not the 4th. Row is not refilled yet.', () => { const G = atStep('tile', 15, 'vizier'); setK(15, 'small', 6); P(0).coins = 20; const t = moves().filter(m => m.act === 'tile' && m.take); eq([[0], [1], [2]], t.map(m => m.take)); mv({ act: 'tile', take: [1] }); eq([17, ['jewels'], 8], [P(0).coins, P(0).res, G.market.length]) });
R('Tile actions', 'RB', 'Bazaars/shrines are optional but need the full price: with 2 gold the Bazaar Stall offers nothing but skip.', () => { const G = atStep('tile', 15, 'vizier'); setK(15, 'small', 6); P(0).coins = 2; eq([{ act: 'tile', skip: 1 }], moves().filter(m => m.act === 'tile')) });
R('Tile actions', 'RB', 'Grand Bazaar (optional): pay 6 gold, take 2 of the first 6 resource cards (15 combinations, never the 7th card).', () => { const G = atStep('tile', 15, 'vizier'); setK(15, 'large', 4); P(0).coins = 20; const t = moves().filter(m => m.act === 'tile' && m.take); eq([15, true], [t.length, t.every(m => m.take.length === 2 && Math.max(...m.take) <= 5)]); mv({ act: 'tile', take: [0, 5] }); eq([14, ['ivory', 'spice']], [P(0).coins, P(0).res.slice().sort()]) });
R('Tile actions', 'RB', 'Grand Bazaar with only 1 resource card left: you may still pay 6 gold to take that one card.', () => { const G = atStep('tile', 15, 'vizier'); setK(15, 'large', 4); P(0).coins = 20; G.market = ['gold']; const t = moves().filter(m => m.act === 'tile' && m.take); eq([[0]], t.map(m => m.take)); mv(t[0]); eq([14, ['gold']], [P(0).coins, P(0).res]) });
R('Tile actions', 'RB', 'Shrine (optional): pay 2 Sages, take the Djinn of your choice among those face up; Sages return to the bag; the Djinn is not replaced until clean-up.', () => { const G = atStep('tile', 15, 'vizier'); setK(15, 'sacred', 6); P(0).el = 3; G.djRow = ['wazira', 'hikma', 'nakhla']; const bag = G.bag.length; const t = moves().filter(m => m.act === 'tile' && m.dj); eq(['hikma', 'nakhla', 'wazira'], [...new Set(t.map(m => m.dj))].sort()); mv(t.find(m => m.dj === 'hikma' && m.pay.el === 2)); eq([1, ['hikma'], 2, bag + 2], [P(0).el, P(0).dj, G.djRow.length, G.bag.length]) });
R('Tile actions', 'RB', 'Shrine alternative price: 1 Sage + 1 Mystic (Mystic discarded).', () => { const G = atStep('tile', 15, 'vizier'); setK(15, 'sacred', 6); P(0).el = 1; P(0).fk = 1; G.djRow = ['wazira']; const t = moves().filter(m => m.act === 'tile' && m.dj); mv(t[0]); eq([0, 0, ['wazira'], 1], [P(0).el, P(0).fk, P(0).dj, G.rdisc.filter(c => c === 'fakir').length]) });
R('Tile actions', 'RB', 'Shrine cannot be used with only 1 Sage and no Mystic (or only Mystics).', () => { const G = atStep('tile', 15, 'vizier'); setK(15, 'sacred', 6); P(0).el = 1; P(0).fk = 0; eq(false, has(m => m.act === 'tile' && m.dj)); P(0).el = 0; P(0).fk = 3; eq(false, has(m => m.act === 'tile' && m.dj)) });
R('Tile actions', 'RB', 'The tile action is that of the tile you ENDED your move on, even if you did not take control of it.', () => { const G = fresh(); setK(15, 'oasis', 8); put(14, ['vizier']); put(15, ['vizier', 'elder']); begin(0); go(14, [[15, 'vizier']]); eq(null, G.board[15].camel); mv({ act: 'tribe' }); eq(true, has(m => m.act === 'tile' && m.place === 15)) });
R('Tile actions', 'RB', 'A second tile controlled through Shadow kill gives NO tile action; only the final tile\'s action is performed.', () => { const G = fresh(); setK(16, 'village', 5); setK(15, 'small', 6); put(14, ['assassin']); put(15, ['assassin']); put(16, ['builder']); begin(0); P(0).coins = 10; go(14, [[15, 'assassin']]); mv({ act: 'tribe', kill: { tile: 16, c: 'builder', fk: 0 } }); const tm = moves().filter(m => m.act === 'tile'); eq(false, tm.some(m => m.place != null)); eq(true, tm.some(m => m.take)); eq(0, G.board[16].pal) });
// ============================================================ MERCHANDISE SALE
R('Sale', 'RB', 'A suit of 1..9 DIFFERENT goods sells for 1, 3, 7, 13, 21, 30, 40, 50, 60 gold.', () => { eq([0, 1, 3, 7, 13, 21, 30, 40, 50, 60], SETVP) });
R('Sale', 'RB', 'Selling discards the cards and pays the table amount from the bank (3 different cards = 7 gold).', () => { const G = atStep('sell', 15, 'vizier', 1, true); P(0).coins = 5; P(0).res = ['gold', 'fish', 'silk', 'gold']; mv({ act: 'sell', kinds: ['fish', 'gold', 'silk'] }); eq([12, ['gold'], 3], [P(0).coins, P(0).res, G.rdisc.length]) });
R('Sale', 'RB', 'You may sell several suits in one turn (rulebook example: 6 different = 30, plus 3 duplicates = 7).', () => { const G = atStep('sell', 15, 'vizier', 1, true); P(0).coins = 0; P(0).res = ['ivory', 'jewels', 'gold', 'papyrus', 'silk', 'spice', 'ivory', 'jewels', 'gold']; mv({ act: 'sell', kinds: ['gold', 'ivory', 'jewels', 'papyrus', 'silk', 'spice'] }); mv({ act: 'sell', kinds: ['gold', 'ivory', 'jewels'] }); eq([37, []], [P(0).coins, P(0).res]) });
R('Sale', 'RB', 'Mystics cannot be sold.', () => { const G = atStep('sell', 15, 'vizier', 1, true); P(0).fk = 3; P(0).res = ['gold']; const r = C.performMove({ act: 'sell', kinds: ['fakir'] }); eq([false, 3], [r.success, P(0).fk]) });
R('Sale', 'RB', 'A suit may contain only different cards: two copies of one kind cannot be sold together.', () => { const G = atStep('sell', 15, 'vizier', 1, true); P(0).res = ['gold', 'gold', 'fish']; const r = C.performMove({ act: 'sell', kinds: ['gold', 'gold'] }); eq(false, r.success) });
R('Sale', 'RB', 'The sale happens at the end of your turn, after tribe and tile actions (not during the move).', () => { fresh(3); put(14, ['vizier']); put(15, ['vizier']); const G = begin(0); P(0).res = ['gold']; eq(false, has(m => m.act === 'sell')); G.step = 'tribe'; G.act = { tile: 15, color: 'vizier', n: 1, tribeDone: false }; eq(false, has(m => m.act === 'sell')); G.step = 'sell'; eq(true, has(m => m.act === 'sell')) });
R('Sale', 'RB', 'Selling is optional: a turn can end with goods kept.', () => { const G = atStep('sell', 15, 'vizier', 1, true); P(0).res = ['gold']; eq(true, has(m => m.act === 'end')) });
// ============================================================ CLEAN-UP
function finishRound() { const G = g(); let k = 0; while (G.phase === 'turn' && k++ < 20) C.endTurn() }
R('Clean-up', 'RB', 'Resource row is refilled to 9 only after all players have played, shifting remaining cards to the front.', () => { const G = fresh(3); begin(0); G.market.splice(0, 3); C.endTurn(); eq(6, G.market.length, 'mid-round'); C.endTurn(); C.endTurn(); eq([9, 'papyrus'], [G.market.length, G.market[0]]) });
R('Clean-up', 'RB', 'Djinn row is refilled to 3 after all players have played.', () => { const G = fresh(3); begin(0); G.djRow.splice(0, 2); C.endTurn(); eq(1, G.djRow.length, 'mid-round'); C.endTurn(); C.endTurn(); eq(3, G.djRow.length) });
R('Clean-up', 'RB', 'When the resource deck is exhausted, discards are reshuffled; with nothing left the row stays short.', () => { const G = fresh(3); begin(0); G.rdisc = ['gold', 'fish']; G.rdeck = []; G.market = []; finishRound(); eq(2, G.market.length); G.rdeck = []; G.rdisc = []; G.market = []; C.refillMarket(); eq(0, G.market.length) });
// ============================================================ END OF GAME
R('End', 'RB', 'A player placing their last camel ends the game at the end of THAT TURN: every other player still takes their actions this turn, then the game ends.', () => { const G = fresh(3); G.pl[0].camels = 1; put(14, ['elder']); put(15, ['elder']); put(20, ['vizier']); put(21, ['vizier']); begin(0); go(14, [[15, 'elder']]); eq(true, G.endTrig); mv({ act: 'tribe' }); mv({ act: 'tile', skip: 1 }); mv({ act: 'end' }); eq([false, 'turn', 1], [!!G.over, G.phase, G.turnIdx], 'game must continue after first player'); C.endTurn(); eq(false, !!G.over, 'after 2nd player'); C.endTurn(); eq(true, !!G.over, 'after 3rd player') });
R('End', 'RB', 'The last camel also ends the game when placed by Shadow kill (second tile) -- the end is triggered by dropping the last camel.', () => { const G = fresh(3); P(0).camels = 2; put(14, ['assassin']); put(15, ['assassin']); put(16, ['builder']); begin(0); go(14, [[15, 'assassin']]); mv({ act: 'tribe', kill: { tile: 16, c: 'builder', fk: 0 } }); eq([0, true], [P(0).camels, G.endTrig]) });
R('End', 'RB', 'The game also ends when no legal meeple move is possible: that player and all after can only use djinn powers; the turn finishes and scores are computed.', () => { const G = fresh(3); put(14, ['vizier']); begin(0); eq(0, C.legalStarts().length); eq('sell', G.step); C.endTurn(); eq(false, !!G.over, 'mid-turn'); C.endTurn(); C.endTurn(); eq(true, !!G.over) });
R('End', 'RB', 'Pieces are conserved over whole games (90 meeples, 54 resource cards, no negatives): computer-vs-computer sweep with the engine invariants checked after every move.', () => { const ai = fs.readFileSync(path.join(__dirname, 'src', 'ai.js'), 'utf8'); vm.runInContext(ai, C, { filename: 'ai' }); run('UI.sim=true;'); const bad = []; try { for (let s = 0; s < 12; s++) { run(`DEFSEED=${900 + s}; newGame({np:${2 + s % 3},seats:[${Array(2 + s % 3).fill('{human:false}').join(',')}]});`); let k = 0; while (!g().over && k++ < 20000) { const sd = C.sideToAct(), m = C.aiMove(sd); if (!m) { bad.push('stuck'); break } C.performMove(m, sd); const v = C.checkInvariants(); if (v.length) { bad.push(s + ':' + v[0]); break } } } } finally { run('UI.sim=false;') } eq([], bad) });
// ============================================================ SCORING
const score = (setup) => { const G = fresh(3); setup(G); return C.scoreOf(G.pl[0]) };
R('Scoring', 'RB', '1 VP per gold coin.', () => { eq(37, score(G => { G.pl[0].coins = 37 }).coins) });
R('Scoring', 'RB', 'Advisors: 1 VP each plus 10 VP for each opponent with strictly fewer Advisors (ties give no bonus).', () => { const G = fresh(3); G.pl[0].vz = 3; G.pl[1].vz = 1; G.pl[2].vz = 1; eq([23, 1, 1], G.pl.map(p => C.scoreOf(p).advisors)); G.pl[2].vz = 3; eq([3 + 10, 3 + 10, 1 + 0], [C.scoreOf(G.pl[0]).advisors, C.scoreOf(G.pl[2]).advisors, C.scoreOf(G.pl[1]).advisors]) });
R('Scoring', 'RB', 'Sages: 2 VP each.', () => { eq(10, score(G => { G.pl[0].el = 5 }).sages) });
R('Scoring', 'UV', 'Djinns: the sum of the VP printed on each Djinn you hold (values live on the cards; the engine table is checked for sum behaviour only).', () => { const s = score(G => { G.pl[0].dj = ['hikma', 'nakhla'] }); eq(DJ.hikma.vp + DJ.nakhla.vp, s.djinns) });
R('Scoring', 'RB', 'Palm trees: 3 VP each, only on tiles you control.', () => { const G = fresh(3); G.board[15].camel = 0; G.board[15].palm = 2; G.board[16].palm = 4; eq(6, C.scoreOf(G.pl[0]).palms) });
R('Scoring', 'RB', 'Palaces: 5 VP each, only on tiles you control.', () => { const G = fresh(3); G.board[15].camel = 0; G.board[15].pal = 2; G.board[16].camel = 1; G.board[16].pal = 3; eq(10, C.scoreOf(G.pl[0]).palaces) });
R('Scoring', 'RB', 'Tiles: the printed value of every tile you control (camel on it).', () => { const G = fresh(3); G.board[15].camel = 0; G.board[15].v = 10; G.board[16].camel = 0; G.board[16].v = 6; G.board[17].camel = 1; G.board[17].v = 15; eq(16, C.scoreOf(G.pl[0]).tiles) });
R('Scoring', 'RB', 'goods: each series of different cards scores the table value (6 different + 3 duplicates of three kinds = 30 + 7).', () => { const s = score(G => { G.pl[0].res = ['ivory', 'jewels', 'gold', 'papyrus', 'silk', 'spice', 'ivory', 'jewels', 'gold'] }); eq(37, s.goods) });
R('Scoring', 'RB', 'goods is scored as the best split into series of different cards (checked against a brute-force best split on 300 random hands).', () => { let seed = 99; const rnd = n => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n }; const kinds = ['ivory', 'jewels', 'gold', 'papyrus', 'silk', 'spice', 'fish', 'wheat', 'pottery'];
  const best = c => { const key = c.join(','); if (best.m[key] !== undefined) return best.m[key]; let top = 0; const idx = c.map((v, i) => v ? i : -1).filter(i => i >= 0); for (let mask = 1; mask < 1 << idx.length; mask++) { const d = c.slice(); let n = 0; idx.forEach((i, j) => { if (mask >> j & 1) { d[i]--; n++ } }); top = Math.max(top, SETVP[n] + best(d)) } return best.m[key] = top }; best.m = {};
  for (let t = 0; t < 300; t++) { const res = [], cnt = kinds.map(() => 0); const n = rnd(20); for (let i = 0; i < n; i++) { const k = rnd(kinds.length); if (cnt[k] < (k < 3 ? 2 : k < 6 ? 4 : 6)) { cnt[k]++; res.push(kinds[k]) } } const G = fresh(3); G.pl[0].res = res; eq(best(cnt), C.scoreOf(G.pl[0]).goods, 'hand ' + res.join(',')) } });
R('Scoring', 'RB', 'Mystics score nothing at game end.', () => { const s = score(G => { G.pl[0].fk = 9 }); eq([0, 50], [s.goods, s.total]) });
R('Scoring', 'RB', 'Total = coins + viziers + elders + djinns + palms + palaces + tiles + goods.', () => { const G = fresh(3); const p = G.pl[0]; p.coins = 11; p.vz = 2; p.el = 3; p.dj = ['sadim']; G.board[15].camel = 0; G.board[15].v = 8; G.board[15].palm = 1; G.board[15].pal = 1; p.res = ['gold', 'fish']; G.pl[1].vz = 0; G.pl[2].vz = 0; eq(11 + 2 + 20 + 6 + DJ.sadim.vp + 3 + 5 + 8 + 3, C.scoreOf(p).total) });
R('Scoring', 'RB', 'Highest total wins; a tie is shared (both listed as winners).', () => { const G = fresh(2); G.pl[0].coins = 10; G.pl[1].coins = 10; G.pl[0].vz = G.pl[1].vz = 0; C.finish(); eq([0, 1], G.over.win); const H = fresh(2); H.pl[0].coins = 11; H.pl[1].coins = 10; H.pl[0].vz = H.pl[1].vz = 0; C.finish(); eq([0], H.over.win) });
// ============================================================ DJINNS (summary sheet: 22 base cards; effects and costs)
const dj = (G, k) => { G.pl[0].dj.push(k); return k };
const djm = k => moves().filter(m => m.act === 'djinn' && m.k === k);
R('Djinn: wild goods', 'SS', 'Each PAIR of Mystics you hold at game end acts as 1 wild goods of your choice (no cost).', () => { const G = fresh(3); const p = G.pl[0]; p.res = ['ivory', 'jewels', 'gold', 'papyrus', 'silk', 'spice', 'fish', 'wheat']; p.fk = 3; const before = C.scoreOf(p).goods; dj(G, 'zarifa'); eq([50, 60], [before, C.scoreOf(p).goods]); p.fk = 1; eq(50, C.scoreOf(p).goods, 'one Mystic is not a pair') });
R('Djinn: 3 meeples', 'SS', 'Cost 1 Sage or 1 Mystic: pick an empty tile (no camel, meeple, palm tree or palace) and place 3 meeples drawn at random from the bag on it.', () => { const G = atStep('tile', 15, 'vizier'); put(15, ['vizier']); dj(G, 'tamuz'); P(0).el = 1; const t = new Set(djm('tamuz').map(m => m.t)); eq(false, t.has(15), 'occupied tile'); G.board[8].palm = 1; eq(false, new Set(djm('tamuz').map(m => m.t)).has(8), 'tile with palm'); G.board[9].camel = 1; eq(false, new Set(djm('tamuz').map(m => m.t)).has(9), 'camel tile'); const bag = G.bag.length; mv(djm('tamuz').find(m => m.t === 20 && m.pay.el === 1)); eq([3, 0, bag - 3 + 1], [G.board[20].m.length, P(0).el, G.bag.length]) });
R('Djinn: gold per djinn', 'SS', 'Each time someone gets a Djinn: 1 gold if it is you, 2 gold if it is an opponent (taking a different Djinn).', () => { const G = fresh(3); dj(G, 'harith'); const c0 = P(0).coins; C.gainDjinn(P(1), 'wazira'); eq(c0 + 2, P(0).coins, 'opponent'); C.gainDjinn(P(0), 'hikma'); eq(c0 + 3, P(0).coins, 'self') });
R('Djinn: protection', 'SS', 'Your Sages and Advisors are protected from Shadows.', () => { const G = fresh(3); put(14, ['assassin']); put(15, ['assassin']); begin(0); P(1).vz = 2; P(1).el = 2; P(1).dj.push('sadim'); go(14, [[15, 'assassin']]); eq(false, kills().some(k => k.kill.pl === 1)); eq(true, kills().length === 0 || kills().every(k => k.kill.pl == null)) });
R('Djinn: palace on Hamlet', 'SS', 'Cost 1 Sage or 1 Mystic: place 1 palace on any Hamlet (anywhere on the board, any time in your turn).', () => { const G = atStep('tile', 15, 'vizier'); setK(10, 'village', 5); setK(11, 'village', 5); dj(G, 'nuraya'); P(0).el = 1; const t = djm('nuraya'); eq([10, 11], [...new Set(t.map(m => m.t))].sort((a, b) => a - b)); mv(t.find(m => m.t === 11)); eq([1, 0, 9], [G.board[11].pal, P(0).el, G.sup.pal]) });
R('Djinn: double builders', 'SS', 'Cost 1 Sage + (1 Sage or 1 Mystic): the gold your Masons get this turn is doubled.', () => { const G = fresh(); for (const i of [8, 9]) setK(i, 'village', 5); put(14, ['builder']); put(15, ['builder']); begin(0); dj(G, 'qirsh'); P(0).el = 2; P(0).coins = 0; go(14, [[15, 'builder']]); eq(0, djm('qirsh').filter(m => m.pay.el === 1 && m.pay.fk === 0).length, '1 elder alone is not enough'); mv(djm('qirsh').find(m => m.pay.el === 2)); mv({ act: 'tribe' }); eq([2 * 2 * 2, 0], [P(0).coins, P(0).el]) });
R('Djinn: palm on Oasis', 'SS', 'Cost 1 Sage or 1 Mystic: place 1 palm tree on any Oasis.', () => { const G = atStep('tile', 15, 'vizier'); setK(10, 'oasis', 8); dj(G, 'wahha'); P(0).fk = 1; const t = djm('wahha'); eq([10], [...new Set(t.map(m => m.t))]); mv(t.find(m => m.pay.fk === 1)); eq([1, 0, 11], [G.board[10].palm, P(0).fk, G.sup.palm]) });
R('Djinn: palace neighbour', 'SS', 'Cost 1 Sage or 1 Mystic: when you place a palace this turn you may drop it on a neighbouring tile instead.', () => { const G = fresh(); setK(15, 'village', 5); put(14, ['vizier']); put(15, ['vizier', 'elder']); begin(0); dj(G, 'burhan'); P(0).el = 1; go(14, [[15, 'vizier']]); mv({ act: 'tribe' }); mv(djm('burhan')[0]); const places = moves().filter(m => m.act === 'tile' && m.place != null).map(m => m.place).sort((a, b) => a - b); eq([9, 15, 14, 16, 21].sort((a, b) => a - b), places); mv({ act: 'tile', place: 16 }); eq([1, 0], [G.board[16].pal, G.board[15].pal]) });
R('Djinn: palm value 5', 'SS', 'Each of your palm trees is worth 5 VP instead of 3.', () => { const G = fresh(3); G.board[15].camel = 0; G.board[15].palm = 2; dj(G, 'nakhla'); eq(10, C.scoreOf(P(0)).palms) });
R('Djinn: double kill', 'SS', 'Cost 1 Sage or 1 Mystic: your Shadows kill 2 meeples of any colour on the same tile, or 2 Sages/Advisors from the same opponent.', () => { const G = fresh(); put(14, ['assassin']); put(15, ['assassin']); put(16, ['builder', 'merchant']); begin(0); dj(G, 'ghulam'); P(0).el = 1; P(1).vz = 2; go(14, [[15, 'assassin']]); mv(djm('ghulam')[0]); const k2 = kills().filter(k => k.kill.c2); eq(true, k2.some(k => k.kill.tile === 16) && k2.some(k => k.kill.pl === 1 && k.kill.c === 'vizier' && k.kill.c2 === 'vizier')); const bag = G.bag.length; mv({ act: 'tribe', kill: { tile: 16, c: 'builder', c2: 'merchant', fk: 0 } }); eq([0, 6], [G.board[16].m.length, P(0).camels]) });
R('Djinn: vizier value 3', 'SS', 'Each of your Advisors is worth 3 VP instead of 1 (the +10 majority bonus is unchanged).', () => { const G = fresh(3); P(0).vz = 2; P(1).vz = 1; P(2).vz = 1; dj(G, 'wazira'); eq(6 + 20, C.scoreOf(P(0)).advisors) });
R('Djinn: kill bonuses', 'SS', 'When your Shadows kill: a Trader -> draw the top resource card; a Mason -> take the gold that Mason would have taken; a Advisor or Sage -> place it in front of you instead of killing it.', () => { const G = fresh(); put(14, ['assassin']); put(15, ['assassin', 'assassin']); put(16, ['merchant']); begin(0); dj(G, 'sirra'); go(14, [[15, 'assassin']]); const top = G.rdeck[0]; mv({ act: 'tribe', kill: { tile: 16, c: 'merchant', fk: 0 } }); eq(1, P(0).res.length + P(0).fk, 'merchant -> top card ' + top); const H = fresh(); for (const i of [9, 10, 11, 15, 16]) setK(i, 'village', 5); put(14, ['assassin']); put(15, ['assassin']); put(10, ['builder']); begin(0); dj(H, 'sirra'); P(0).coins = 0; go(14, [[15, 'assassin']]); mv({ act: 'tribe', kill: { tile: 10, c: 'builder', fk: 0 } }); eq(blues(10), P(0).coins, 'builder gold (blue tiles around victim)'); const K = fresh(); put(14, ['assassin']); put(15, ['assassin']); begin(0); dj(K, 'sirra'); P(1).vz = 2; go(14, [[15, 'assassin']]); mv({ act: 'tribe', kill: { pl: 1, c: 'vizier', fk: 0 } }); eq([1, 1], [P(1).vz, P(0).vz]) });
R('Djinn: cheaper bid', 'SS', 'Cost 1+ Mystics, when bidding: each Mystic discarded lowers your bidding cost by one spot (you still take the chosen spot).', () => { const G = fresh(3); const who = G.bidQueue[0].p; dj(G, 'dalil'); G.pl[0].dj = []; P(who).dj.push('dalil'); P(who).fk = 2; const spot18 = G.track.findIndex(t => t.cost === 18); const m = moves().find(m => m.spot === spot18 && m.fk === 1); eq(true, !!m, 'fk:1 bid on the 18 spot offered'); mv(m); eq([38, 1, spot18], [P(who).coins, P(who).fk, G.bids[0].spot]) });
R('Djinn: palm neighbour', 'SS', 'Cost 1 Sage or 1 Mystic: when you build a palm tree this turn you may place it on a neighbouring tile instead.', () => { const G = fresh(); setK(15, 'oasis', 8); put(14, ['vizier']); put(15, ['vizier', 'elder']); begin(0); dj(G, 'rawda'); P(0).fk = 1; go(14, [[15, 'vizier']]); mv({ act: 'tribe' }); mv(djm('rawda')[0]); eq(true, has(m => m.act === 'tile' && m.place === 16)); mv({ act: 'tile', place: 16 }); eq([1, 0], [G.board[16].palm, G.board[15].palm]) });
R('Djinn: free camel', 'SS', 'Cost 1 Sage + (1 Sage or 1 Mystic): take control of 1 empty tile (no camel, meeple, palm or palace) and place a camel on it.', () => { const G = atStep('tile', 15, 'vizier'); put(15, ['vizier']); dj(G, 'jamal'); P(0).el = 1; P(0).fk = 1; const t = djm('jamal'); eq(false, t.some(m => m.t === 15), 'occupied'); mv(t.find(m => m.t === 20 && m.pay.el === 1 && m.pay.fk === 1)); eq([0, 7, 0, 0], [G.board[20].camel, P(0).camels, P(0).el, P(0).fk]) });
R('Djinn: coin per drop', 'SS', 'Each time a meeple is dropped on one of your tiles during a move: 1 gold if you did the move, 2 gold if an opponent did.', () => { const G = fresh(); G.board[15].camel = 0; put(14, ['vizier']); put(15, ['vizier']); begin(1); dj(G, 'tariq'); G.pl[1].dj = []; const c0 = P(0).coins; go(14, [[15, 'vizier']]); eq(c0 + 2, P(0).coins, 'rival drop'); const H = fresh(); H.board[15].camel = 0; put(14, ['vizier']); put(15, ['vizier']); begin(0); dj(H, 'tariq'); const d0 = P(0).coins; go(14, [[15, 'vizier']]); eq(d0 + 1, P(0).coins, 'own drop') });
R('Djinn: gold per palace', 'SS', 'Each time a palace is placed: 1 gold if you placed it, 2 gold if an opponent did.', () => { const G = fresh(); dj(G, 'qasra'); const c0 = P(0).coins; G.cur = 1; C.placePalace(P(1), 15); eq(c0 + 2, P(0).coins); C.placePalace(P(0), 16); eq(c0 + 3, P(0).coins) });
R('Djinn: gold per kill', 'SS', 'Each time Shadows kill: 1 gold if you did the killing, 2 gold if an opponent did.', () => { const G = fresh(); put(14, ['assassin']); put(15, ['assassin']); put(16, ['builder']); begin(0); dj(G, 'khanjar'); P(1).dj.push('khanjar'); const a = P(0).coins, b = P(1).coins; go(14, [[15, 'assassin']]); mv({ act: 'tribe', kill: { tile: 16, c: 'builder', fk: 0 } }); eq([a + 1, b + 2], [P(0).coins, P(1).coins], 'killer holding it +1; the other holder +2') });
R('Djinn: elder value 4', 'SS', 'Each of your Sages is worth 4 VP instead of 2.', () => { const G = fresh(3); P(0).el = 3; dj(G, 'hikma'); eq(12, C.scoreOf(P(0)).sages) });
R('Djinn: pick a djinn', 'SS', 'Cost 1 Sage + (1 Sage or 1 Mystic): draw the top 3 Djinns, keep 1, discard the other 2.', () => { const G = atStep('tile', 15, 'vizier'); dj(G, 'ruya'); P(0).el = 2; const deck = G.djDeck.slice(0, 3); mv(djm('ruya').find(m => m.pay.el === 2)); eq(true, !!G.q, 'question opened'); eq(3, G.q.opts.length); mv({ act: 'q', i: 1 }); eq([deck[1], 0], [P(0).dj[P(0).dj.length - 1], P(0).el]); eq(true, G.djDisc.includes(deck[0]) && G.djDisc.includes(deck[2])) });
R('Djinn: take a card', 'SS', 'Cost 1 Mystic: take the top card of the resource draw pile.', () => { const G = atStep('tile', 15, 'vizier'); dj(G, 'suqra'); P(0).fk = 1; eq(0, djm('suqra').filter(m => m.pay.el).length, 'elder cannot pay'); const top = G.rdeck[0]; mv(djm('suqra')[0]); eq([top === 'fakir' ? 1 : 0, 54 - 9 - 1], [P(0).fk, G.rdeck.length]) });
R('Djinn: free camel on meeples', 'SS', 'Cost 1 Sage + (1 Sage or 1 Mystic): take control of 1 tile that holds only meeples (no camel, palm tree or palace); place a camel on it.', () => { const G = atStep('tile', 15, 'vizier'); put(20, ['builder', 'elder']); put(21, ['builder']); G.board[21].palm = 1; put(22, ['builder']); G.board[22].camel = 1; dj(G, 'fath'); P(0).el = 2; const t = new Set(djm('fath').map(m => m.t)); eq([20], [...t], 'only tile 20 qualifies'); mv(djm('fath').find(m => m.pay.el === 2)); eq([0, 7], [G.board[20].camel, P(0).camels]) });
R('Djinn: once per turn / timing', 'SS', 'A Djinn power with a cost can only be used once per turn, only on the turn of its owner, and can be used the moment you get the Djinn.', () => { const G = atStep('tile', 15, 'vizier'); setK(15, 'sacred', 6); G.djRow = ['wahha', 'hikma']; P(0).el = 4; setK(10, 'oasis', 8); const pay = moves().find(m => m.dj === 'wahha'); mv(pay); const first = djm('wahha'); eq(true, first.length > 0, 'usable right away'); mv(first[0]); eq(0, djm('wahha').length, 'second use same turn'); P(0).el = 4; eq(0, djm('wahha').length, 'still once per turn'); const H = atStep('tile', 15, 'vizier'); P(1).dj.push('wahha'); P(1).el = 3; eq(0, moves().filter(m => m.act === 'djinn' && m.k === 'wahha').length, 'not on a rival\'s turn') });
// ============================================================ RUN
const only = process.argv.includes('--md');
if (only) {
  const lines = ['# Sands of Qamar: rules checklist (W430)', '', 'Every rule of the published base game that this adaptation must follow, one number per rule. Each rule has exactly one assertion in `logic-test.js` (same number), run against the real engine in `src/`.', '',
    'Sources: **RB** = the published rulebook text, **SS** = the player summary sheet (turn flow and the 22 djinn effects and costs), **UV** = printed on tiles/cards, not in any text I could read, so the test only checks the engine against its own data table (not independent proof).', '',
    'Out of scope here: the expansions (Crafters, Wonder Cities, Cutpurses, promo djinns, 5th player). Not testable from text: exact VP printed on each djinn and on each tile (marked UV).', ''];
  let grp = '', n = 0; for (const r of RULES) { n++; if (r.grp !== grp) { grp = r.grp; lines.push('', '## ' + grp.replace(/^Djinn: .*/, 'Djinns').replace(/^Djinns$/, 'Djinns'), '') } lines.push(`${n}. [${r.src}] ${r.text}${r.grp.startsWith('Djinn:') ? '  _(' + r.grp.slice(7) + ')_' : ''}`) }
  const ren = { viziers: 'advisors', vizier: 'advisor', elders: 'sages', elder: 'sage', builders: 'masons', builder: 'mason', assassins: 'shadows', assassin: 'shadow', merchants: 'traders', merchant: 'trader', fakirs: 'mystics', fakir: 'mystic' }; fs.writeFileSync(path.join(__dirname, 'RULES-CHECKLIST.md'), lines.join('\n').replace(/\b(viziers?|elders?|builders?|assassins?|merchants?|fakirs?)\b/g, w => ren[w]).replace(/\n## Djinns\n\n(?=[\s\S]*\n## Djinns\n)/g, '\n') + '\n'); console.log('wrote RULES-CHECKLIST.md with', n, 'rules'); process.exit(0);
}
let pass = 0; const failed = [];
RULES.forEach((r, i) => { const n = i + 1; try { r.fn(); pass++ } catch (e) { failed.push(n); console.log(`FAIL rule ${n} [${r.grp}] "${r.text.slice(0, 50)}" expected ${e.exp !== undefined ? e.exp : 'no error'}, got ${e.exp !== undefined ? e.got : 'threw ' + e.message}`) } });
console.log(`logic-test: ${RULES.length} rules, ${pass} pass, ${failed.length} fail${failed.length ? ' (' + failed.join(',') + ')' : ''}`);
process.exit(failed.length ? 1 : 0);
